/*
interface RainDrop {
	x: number;
	y: number;
	vx: number;
	vy: number;
}
*/


let canvasSize; 
let marginX, marginY;
let cSize;
let rainGraphics;

const maxStep = 5;
const cellCount = 5;

let umbrellas;
let rainDrops;

let seed = 0;
let step = 0;
let bgColor;

function setup() {
	document.body.style.background = "#333";


	canvasSize = max(windowWidth, windowHeight);
	createCanvas(canvasSize*0.65, canvasSize, P2D);
	colorMode(HSB, 360, 100, 100, 100);
	pixelDensity(2);
	frameRate(60);
	noiseDetail(24, 0.5);

	rainGraphics = createGraphics(width, height, P2D);
	rainGraphics.colorMode(HSB, 360, 100, 100, 100);
	rainGraphics.pixelDensity(2);

	bgColor = color(35,2,98,40);
	marginX = width * 0.2;
	cSize = width - marginX * 2;
	marginY = (height-cSize)/2;

	umbrellas = new Array(cellCount * cellCount).fill(0).map((_, i) => {
		const x = i % cellCount;
		const y = floor(i / cellCount);

		return {
			x: ((x + (y % 2 ? 0.25 : 0.75)) / cellCount) * cSize + marginX,
			y: ((y + 0.5) / cellCount) * cSize + marginY,
			r: 0,
			vr: 0,
			radius: ((cSize / cellCount) * 0.9) / 2,
		};
	});

	rainDrops = new Array(1000).fill(0).map(() => {
		return {
			x: getRandomRainX(),
			y: random(height)-height,
			vx: 0,
			vy: 1,
		};
	});
}

function draw() {
	background(0);
	rainGraphics.background(bgColor);

	rainDrops.forEach((rd, i) => {
		rd.vx *= 0.96;
		rd.vy *= 0.96;

		rd.vx += (noise(rd.x * 0.001, rd.y * 0.01, frameCount * 0.01) * 2 - 1) * 0.1;
		rd.vy += random(0.25, 0.8) * 0.75;

		rd.x += rd.vx;
		rd.y += rd.vy;

		umbrellas.forEach((umbrella) => {
			const hit = getCollision(rd, umbrella);
			if (hit) {
				rd.x += hit.offsetX;
				rd.y += hit.offsetY;
				rd.vx *= 0.9;
				rd.vy *= 0.9;

				const vlen = (rd.vx ** 2 + rd.vy ** 2) ** 0.5;
				const bounce = random(0.05, 0.3) * vlen * random(1) ** 5;
				rd.vx += hit.offsetX * bounce;
				rd.vy += hit.offsetY * bounce;
			}
		});

		if (rd.y > height + 10) {
			rd.y = 0;
			rd.x = getRandomRainX();
			rd.vx = 0;
		}

		rainGraphics.stroke(210, 60, 40);
		rainGraphics.strokeWeight(1.5);
		rainGraphics.line(rd.x - rd.vx, rd.y - rd.vy, rd.x, rd.y);
	});

	image(rainGraphics, 0,0);

	push();
	drawUmbrellas();
	pop();
}

function getRandomRainX(){
	const rainWidth = map(cos(frameCount*0.002), -1, 1, cSize*0.1, cSize*0.4);
	return random(rainWidth) -
		rainWidth / 2 +
		width / 2 +
		(cos(frameCount * 0.005) * (cSize-rainWidth+marginX/2)) / 2;
}

function getCollision(rainDrop, umbrella) {
	if(umbrella.x-umbrella.radius > rainDrop.x) return null;
	if(umbrella.x+umbrella.radius < rainDrop.x) return null;
	if(umbrella.y-umbrella.radius > rainDrop.y) return null;
	if(umbrella.y+umbrella.radius < rainDrop.y) return null;

	const diffX = umbrella.x - rainDrop.x;
	const diffY = umbrella.y - rainDrop.y;
	const distSqrt = diffX * diffX + diffY * diffY;

	const radius = umbrella.radius * 0.75;

	if (distSqrt < radius * radius) {
		const dist = distSqrt ** 0.5;
		const diffR = radius - dist;
		return {
			offsetX: -(diffX / dist) * diffR,
			offsetY: -(diffY / dist) * diffR,
		};
	}

	return null;
}

function drawUmbrellas() {
	rectMode(CENTER);
	strokeWeight(2);

	if (frameCount % 10 === 0) {
		const luckyUmbrella = umbrellas[floor(random(umbrellas.length))];
		luckyUmbrella.vr += random(0.25, 0.5) * (random() > 0.5 ? -1 : 1);
	}

	const umbrellaColor = color(0);
	umbrellas.forEach((umbrella, i) => {
		const r = umbrella.radius * 2;
		const dir = 0;

		umbrella.vr = umbrella.vr * 0.95;
		umbrella.r += umbrella.vr * 0.25;
		umbrella.vr = constrain(umbrella.vr + (dir + 100 - (umbrella.r + 100)) * 0.2, -1, 1);

		push();
		translate(umbrella.x, umbrella.y);
		rotate(umbrella.r);

		// Umbrella
		rotate(PI);
		noStroke();
		fill(umbrellaColor);
		arc(0, 0, r * 0.75, r * 0.75, -PI * 0, PI * 1);
		stroke(umbrellaColor);
		const lineEnd = -r / 3;
		line(0, (r * 0.75) / 2 + 4, 0, lineEnd);
		const handleR = r * 0.1;
		translate(handleR / 2, 0);
		noFill();
		arc(0, lineEnd, handleR, handleR, PI, TWO_PI);

		pop();
	});
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
